d buildGatewayWebSocketUrl import\n\nFixes #468","tree":{"sha":"5531aee465ac0aeec209a1c340cfee16f23df290","url":"https://api.github.com/repos/bochek/bochek-mission-control/git/trees/5531aee465ac0aeec209a1c340cfee16f23df290"},"url":"https://api.github.com/repos/bochek/bochek-mission-control/git/commits/e56203b6a8cc64f127f89e077e2120ffb2c3d5a3","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/93952610?v=4","events_url":"https://api.github.com/users/0xNyk/events{/privacy}","followers_url":"https://api.github.com/users/0xNyk/followers","following_url":"https://api.github.com/users/0xNyk/following{/other_user}","gists_url":"https://api.github.com/users/0xNyk/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/0xNyk","id":93952610,"login":"0xNyk","node_id":"U_kgDOBZmaYg","organizations_url":"https://api.github.com/users/0xNyk/orgs","received_events_url":"https://api.github.com/users/0xNyk/received_events","repos_url":"https://api.github.com/users/0xNyk/repos","site_admin":false,"starred_url":"https://api.github.com/users/0xNyk/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/0xNyk/subscriptions","type":"User","url":"https://api.github.com/users/0xNyk","user_view_type":"public"},"html_url":"https://github.com/bochek/bochek-mission-control/commit/e56203b6a8cc64f127f89e077e2120ffb2c3d5a3","node_id":"C_kwDORzq8ntoAKGU1NjIwM2I2YThjYzY0ZjEyN2Y4OWUwNzdlMjEyMGZmYjJjM2Q1YTM","parents":[{"html_url":"https://github.com/bochek/bochek-mission-control/commit/34cbc351a1824327770bf70842ac50ca840632ca","sha":"34cbc351a1824327770bf70842ac50ca840632ca","url":"https://api.github.com/repos/bochek/bochek-mission-control/commits/34cbc351a1824327770bf70842ac50ca840632ca"}],"sha":"e56203b6a8cc64f127f89e077e2120ffb2c3d5a3","url":"https://api.github.com/repos/bochek/bochek-mission-control/commits/e56203b6a8cc64f127f89e077e2120ffb2c3d5a3"},